def dedupe(xs: list[int]) -> list[int]:
    # Keep the LAST occurrence of each value, preserving the order of those last positions.
    seen: set[int] = set()
    out: list[int] = []
    for x in reversed(xs):
        if x not in seen:
            seen.add(x)
            out.append(x)
    out.reverse()
    return out
